      if (!u || !u.channelId) continue;
      if (!channels[u.channelId]) {
        channels[u.channelId] = { channelName: u.channelName || '', rssUrl: u.rssUrl || '',
                                  lastVideoId: u.lastVideoId || '', subscribers: [] };
      }
      channels[u.channelId].subscribers.push({ chatId: String(chatId), lang: 'en' });
    }
  } else if (parsed.channelId) {
    channels[parsed.channelId] = { channelName: parsed.channelName || '', rssUrl: parsed.rssUrl || '',
                                   lastVideoId: parsed.lastVideoId || '',
                                   subscribers: [{ chatId: '1087117148', lang: 'en' }] };
  }
  parsed = { channels };
}

const channels = parsed.channels;

// plain string subscribers (pre-language versions) become English by default
for (const id of Object.keys(channels)) {
  channels[id].subscribers = (channels[id].subscribers || []).map(s =>
    typeof s === 'string' ? { chatId: s, lang: 'en' } : s
  );
}

return Object.keys(channels)
  .filter(id => channels[id] && channels[id].rssUrl && channels[id].subscribers.length)
  .map(id => ({ json: Object.assign({ channelId: id }, channels[id]) }));

