// Remember what this person asked for, so the next link they send
// is understood without them having to reply to anything.
const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};

const cb = $('Telegram Trigger').first().json.callback_query;
const chatId = String(cb.message.chat.id);

store.pending[chatId] = {
  action: 'sum',
  lang: cb.data.endsWith('_AR') ? 'ar' : 'en',
  at: Date.now()
};

return $input.all();

