const chatId = String(cb.message.chat.id);

store.pending[chatId] = {
  action: 'mon',
  lang: '',
  at: Date.now()
};

return $input.all();

// A link just arrived. Work out what the person wanted, using two signals.
const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};

const msg = $('Telegram Trigger').first().json.message;
const chatId = String(msg.chat.id);
const link = msg.text;
const repliedTo = (msg.reply_to_message && msg.reply_to_message.text) || '';

let action = '';
let lang = '';

// 1. they replied to one of our prompts - read it straight off
if (/summar/i.test(repliedTo)) action = 'sum';
else if (/channel/i.test(repliedTo)) action = 'mon';

// 2. otherwise, the button they pressed earlier. One hour, then it's stale.
if (!action) {
  const p = store.pending[chatId];
  if (p && Date.now() - p.at < 60 * 60 * 1000) {
    action = p.action;
    lang = p.lang || '';
  }
}

// the choice is used once, then forgotten
delete store.pending[chatId];

// remember the link itself. Buttons pressed after this read it from here
// instead of relying on Telegram attaching a reply, which is fragile.
store.links = store.links || {};
store.links[chatId] = { link, at: Date.now() };

let route = 'ask';                       // nothing known - go ask them
if (action === 'sum') route = lang ? 'sum_ready' : 'sum';
else if (action === 'mon') route = 'mon';

return [{ json: {
  chatId, link, route, lang,
  // keep the original message shape so downstream nodes can still reply to it
  message: { text: link, message_id: msg.message_id, chat: msg.chat }
} }];
